'use strict';
const SETTINGS_URL='https://proud-manifestation-production-3f2d.up.railway.app/settings#meta-connections';
function assessFreshness(input, previous={}) {
  const issues=[];const badFeeds=new Set();const add=(feed,text)=>{badFeeds.add(feed);issues.push(text);};
  function body(name,array=true){const r=input[name];if(!r||r.error||r.statusCode<200||r.statusCode>=300||!Number.isInteger(r.statusCode)||(array?!Array.isArray(r.body):!r.body||typeof r.body!=='object')){add(name.startsWith('ads')?'ads':name.startsWith('pages')?'pages':'monitor',name+' could not be verified');return array?[]:null;}const total=String(r.headers?.['content-range']??'').match(/\/(\d+)$/);if(array&&(r.body.length>=1000||total&&Number(total[1])>r.body.length))add('monitor',name+' query is incomplete');return r.body;}
  const targets=body('targets');const accounts=body('accounts');const studios=body('studios');const adsRows=body('adsWarehouse');const pagesRows=body('pagesWarehouse');const ads=body('adsSource',false);const pages=body('pagesSource',false);
  const names=new Map(studios.map(s=>[s.id,s.studio_name]));const active=targets.filter(t=>t.organization_id===input.organizationId&&t.account_id===input.accountId);
  if(!active.some(t=>t.asset_type==='ad_account')||!active.some(t=>t.asset_type==='page'))add('monitor','Facebook reporting mappings are missing');
  const account=accounts.find(a=>a.id===input.accountId);let expiryWarning='';
  if(!account||account.connection_status!=='connected')add('monitor','Facebook connection needs attention');
  if(account?.token_expires_at){const expiry=Date.parse(account.token_expires_at);if(!Number.isFinite(expiry))add('monitor','Facebook credential expiration could not be verified');else if(expiry<=Date.parse(input.now)+7*86400000){expiryWarning=account.token_expires_at;issues.push('Facebook needs reconnecting soon; credential expires '+account.token_expires_at.slice(0,10));}}
  const adsUnavailable=!ads||!Array.isArray(ads.accounts);
  const pagesUnavailable=!pages||pages.success!==true||!Array.isArray(pages.records);
  if(adsUnavailable)add('ads','Facebook Ads source access failed');if(pagesUnavailable)add('pages','Facebook Page Insights source access failed');
  for(const target of active){const name=names.get(target.studio_id)||'Studio '+target.studio_id;
    if(target.asset_type==='ad_account'&&!adsUnavailable){const source=ads.accounts.find(a=>a.account?.id===target.asset_id);if(!source||source.success!==true||!Array.isArray(source.insights)){add('ads',name+': Ads source access failed');continue;}const delivered=source.insights.filter(r=>r.date_start===input.expectedDate);if(source.insights.some(r=>r.date_start!==input.expectedDate)||source.insights.length>=25){add('ads',name+': Ads source coverage needs verification');continue;}const stored=adsRows.filter(r=>r.studio_id===target.studio_id&&r.account_id===target.asset_id&&r.date_start===input.expectedDate);const keys=new Set(stored.map(r=>r.ad_id));if(keys.size!==stored.length||stored.some(r=>r.spend===null||!Number.isFinite(Number(r.spend))))add('ads',name+': stored Ads records are incomplete');if(delivered.some(r=>!keys.has(r.ad_id)))add('ads',name+': Ads data did not reach the warehouse for '+input.expectedDate);
    }else if(target.asset_type==='page'&&!pagesUnavailable){const source=pages.records.filter(r=>r.page_id===target.asset_id);if(source.some(r=>r.error)){add('pages',name+': Page Insights source access failed');continue;}const daily=source.filter(r=>r.period==='day'&&String(r.insight_date).slice(0,10)===input.expectedDate);if(!daily.length){add('pages',name+': no daily Page Insights returned for '+input.expectedDate);continue;}const stored=pagesRows.filter(r=>r.studio_id===target.studio_id&&r.page_id===target.asset_id&&r.insight_date===input.expectedDate);const keys=new Set(stored.map(r=>r.metric+':'+r.period));if(keys.size!==stored.length||stored.some(r=>r.value===null||!Number.isFinite(Number(r.value))))add('pages',name+': stored Page Insights are incomplete');if(daily.some(r=>!keys.has(r.metric+':'+r.period)))add('pages',name+': Page Insights did not reach the warehouse for '+input.expectedDate);}
  }
  const feeds=[...badFeeds].sort();const signature=feeds.length||expiryWarning?JSON.stringify({feeds,expiryWarning}):'';
  const action=signature&&signature!==previous.signature?'alert':!signature&&previous.signature?'recovered':'quiet';
  return {action,signature,issueFeeds:feeds,expectedDate:input.expectedDate,issues:[...new Set(issues)],subject:action==='recovered'?'SASHA: Facebook reporting recovered':'SASHA: Facebook reporting needs attention',text:action==='recovered'?'Facebook Ads and Page Insights are verified for '+input.expectedDate+'. The reporting gap has cleared.': 'Facebook reporting needs attention for '+input.expectedDate+'.\n\n'+[...new Set(issues)].map(s=>'- '+s).join('\n')+'\n\nMissing data is not verified zero spending. Review the import executions; reconnect Facebook here if needed:\n'+SETTINGS_URL};
}
function assessImportError(event,previous={}){const feed={'z5Mww3blBHS89UYu':'ads','7OMm5L5fprv3Lh5o':'pages'}[event?.workflow?.id];if(!feed)return {action:'quiet',signature:previous.signature||'',issueFeeds:previous.issueFeeds||[],issues:[]};if((previous.issueFeeds||[]).includes(feed))return {action:'quiet',signature:previous.signature||'',issueFeeds:previous.issueFeeds,issues:[]};const feeds=[...new Set([...(previous.issueFeeds||[]),feed])].sort();let expiryWarning='';try{expiryWarning=JSON.parse(previous.signature||'{}').expiryWarning||'';}catch{}const signature=JSON.stringify({feeds,expiryWarning});return {action:signature===previous.signature?'quiet':'alert',signature,issueFeeds:feeds,issues:[feed+' import failed'],subject:'SASHA: Facebook import failed',text:'The scheduled Facebook '+(feed==='ads'?'Ads':'Page Insights')+' import failed. Recent dashboard data may be incomplete; missing data is not verified zero spending.\n\nReview the failed workflow in n8n. If Facebook requires reconnection, use:\n'+SETTINGS_URL};}


const context=$('Check Context').first().json;const result=assessFreshness({...context,targets:$('Read Active Facebook Targets').first().json,accounts:$('Read Facebook Connection Health').first().json,studios:$('Read Studio Names').first().json,adsSource:$('Verify Facebook Ads Source').first().json,pagesSource:$('Verify Facebook Page Source').first().json,adsWarehouse:$('Read Yesterday Ads Warehouse').first().json,pagesWarehouse:$('Read Yesterday Page Warehouse').first().json},$getWorkflowStaticData('global'));return [{json:{...result,dryRun:context.dryRun,checkedAt:context.now}}];

